diff --git a/libil2cpp/vm/AssemblyShadowOwnedPhysicalNames.h b/libil2cpp/vm/AssemblyShadowOwnedPhysicalNames.h
index 2b446fb..da06714 100644
--- a/libil2cpp/vm/AssemblyShadowOwnedPhysicalNames.h
+++ b/libil2cpp/vm/AssemblyShadowOwnedPhysicalNames.h
@@ -10,6 +10,7 @@
 #include <cstring>
 #include <limits>
 #include "AssemblyShadowExecutionRegistrationWitness.h"
+#include "AssemblyShadowObservedTypeShape.h"

 namespace il2cpp { namespace vm { namespace assembly_shadow_owned_physical_names {

@@ -31,6 +32,7 @@ struct RowView {
     size_t registrySlot=kRegistrationSlots;
     assembly_shadow_execution_witness::Source registrationSource=
         assembly_shadow_execution_witness::Source::None;
+    assembly_shadow_observed_type_shape::RawEvidence observedShape{};
 };
 class Capture final {
     struct Span {uint32_t offset=0,bytes=0;};
@@ -39,6 +41,7 @@ class Capture final {
         uint16_t registrySlot=static_cast<uint16_t>(kRegistrationSlots);
         assembly_shadow_execution_witness::Source registrationSource=
             assembly_shadow_execution_witness::Source::None;
+        assembly_shadow_observed_type_shape::RawEvidence observedShape{};
     };
     enum class Stage:uint8_t {New, Collecting, Sealed, Failed};
     std::array<Row,kMaximumRows> rows_{};
@@ -95,7 +98,8 @@ public:
     }
     bool Add(size_t registrationSlot,
              assembly_shadow_execution_witness::Source registrationSource,
-             const char* assembly,const char* nameSpace,const char* simpleName) noexcept {
+             const char* assembly,const char* nameSpace,const char* simpleName,
+             assembly_shadow_observed_type_shape::RawEvidence observedShape={}) noexcept {
         if(stage_!=Stage::Collecting || firstError_!=Error::None)
             return Fail(Error::BadPhase);
         if(count_==kMaximumRows)return Fail(Error::TooManyRows);
@@ -111,6 +115,7 @@ public:
            !Append(simpleName,row.simpleName))return false;
         row.registrySlot=static_cast<uint16_t>(registrationSlot);
         row.registrationSource=registrationSource;
+        row.observedShape=observedShape;
         usedRegistrationSlots_[registrationSlot]=1;
         ++count_;
         return true;
@@ -136,6 +141,13 @@ public:
         out.simpleName={text_.data()+row.simpleName.offset,row.simpleName.bytes};
         out.registrySlot=row.registrySlot;
         out.registrationSource=row.registrationSource;
+        out.observedShape=row.observedShape;
+        return true;
+    }
+    bool AllObservedShapesFromMatchedCallbacks() const noexcept {
+        if(!Complete())return false;
+        for(size_t i=0;i<count_;++i)
+            if(!rows_[i].observedShape.observedFromMatchedPhysicalCallback)return false;
         return true;
     }
     bool RejectInvalidSource() noexcept{return Fail(Error::MissingName);}
@@ -158,6 +170,7 @@ struct Receipt {
     uint64_t registryRevisionBefore=0,registryRevisionAfter=0;
     bool namesCopiedFromMatchedEnumeratorCallbacks=false;
     bool allRowsBoundToObservedRegistry=false;
+    bool allObservedTypeShapeRowsFromMatchedCallbacks=false;
     bool classPointerOwnershipProven=false;
     bool metadataPointerLifetimeProven=false;
     bool completeExecutionTypeKeys=false;
diff --git a/libil2cpp/vm/AssemblyShadowOwnedPhysicalNamesSource.inl b/libil2cpp/vm/AssemblyShadowOwnedPhysicalNamesSource.inl
index 4093701..4e66890 100644
--- a/libil2cpp/vm/AssemblyShadowOwnedPhysicalNamesSource.inl
+++ b/libil2cpp/vm/AssemblyShadowOwnedPhysicalNamesSource.inl
@@ -7,11 +7,17 @@ bool AssemblyShadow::TryCaptureOwnedObservedPhysicalNames(
 {
     namespace physical=assembly_shadow_physical_membership;
     namespace owned=assembly_shadow_owned_physical_names;
+    namespace shape=assembly_shadow_observed_type_shape;
+    // Source-owned typed constants must agree with the actual installed ABI.
+    static_assert(static_cast<uint8_t>(IL2CPP_TYPE_CLASS)==shape::kClassTypeCode &&
+                  static_cast<uint8_t>(IL2CPP_TYPE_VALUETYPE)==shape::kValueTypeCode,
+                  "Physical shape type codes differ from the pinned IL2CPP ABI");
     receipt=owned::Receipt{};
     auto reject=[&](owned::Error why)->bool {
         if(receipt.error==owned::Error::None)receipt.error=why;
         receipt.namesCopiedFromMatchedEnumeratorCallbacks=false;
         receipt.allRowsBoundToObservedRegistry=false;
+        receipt.allObservedTypeShapeRowsFromMatchedCallbacks=false;
         names.Revoke();
         membershipScratch.Scrub();
         return false;
@@ -64,9 +70,21 @@ bool AssemblyShadow::TryCaptureOwnedObservedPhysicalNames(
                 context.names->RejectInvalidBinding();
                 return;
             }
+            // All these Il2CppClass fields are in its always-valid header.
+            // Read them ONLY at the matched callback while metadata lock
+            // and initial-session lifetime admission are both held. Copy
+            // primitive bits; never retain metadata/generic/class pointers.
+            shape::RawEvidence rawShape{};
+            rawShape.byvalTypeCode=static_cast<uint8_t>(klass->byval_arg.type);
+            rawShape.arrayRank=klass->rank;
+            rawShape.hasTypeMetadataHandle=klass->typeMetadataHandle!=nullptr;
+            rawShape.hasDeclaringType=klass->declaringType!=nullptr;
+            rawShape.hasConstructedGenericClass=klass->generic_class!=nullptr;
+            rawShape.isGenericDefinition=klass->is_generic!=0;
+            rawShape.observedFromMatchedPhysicalCallback=true;
             context.names->Add(registeredSlot,registeredSource,
                                klass->image->assembly->aname.name,
-                               klass->namespaze,klass->name);
+                               klass->namespaze,klass->name,rawShape);
         },&context);
     }
     receipt.matchedClasses=membershipScratch.Matched();
@@ -89,7 +107,10 @@ bool AssemblyShadow::TryCaptureOwnedObservedPhysicalNames(
     if(!membershipScratch.FullyMatched() ||
        !names.Seal(membershipScratch.Observed()))
         return reject(owned::Error::CountMismatch);
+    if(!names.AllObservedShapesFromMatchedCallbacks())
+        return reject(owned::Error::NameCaptureFailed);
     membershipScratch.Scrub();
+    receipt.allObservedTypeShapeRowsFromMatchedCallbacks=true;
     receipt.ownedRows=names.Count();
     receipt.ownedTextBytes=names.TextBytes();
     receipt.boundRegistrationRows=names.Count();
